// Rebuilds content/widget-styles.js from shared/theme.css + content/widget.css.
// Run with:  node tools/build-styles.js   (only needed if you edit those CSS files)
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const css =
  fs.readFileSync(path.join(root, 'shared/theme.css'), 'utf8') + '\n' +
  fs.readFileSync(path.join(root, 'content/widget.css'), 'utf8');
const out =
  '// AUTO-GENERATED by tools/build-styles.js — edit shared/theme.css or content/widget.css instead.\n' +
  'globalThis.CF_WIDGET_CSS = ' + JSON.stringify(css) + ';\n';
fs.writeFileSync(path.join(root, 'content/widget-styles.js'), out);
console.log('wrote content/widget-styles.js (' + out.length + ' bytes)');
